# area: typeddict
# hypothesis: Required and NotRequired keys are enforced only by the checker, so a dict literal missing the Required key is rejected statically yet builds at runtime, and reading the NotRequired key 'year' raises KeyError when it is absent.
from typing import NotRequired, Required, TypedDict, reveal_type


class Movie(TypedDict):
    title: Required[str]
    year: NotRequired[int]


def year_of(m: Movie) -> int:
    return m['year']  # expect-error: 'year' is NotRequired


def bad_build() -> Movie:
    return {'year': 1999}  # expect-error: missing required 'title'


m: Movie = {'title': 'Heat'}
reveal_type(m.get('year'))


def probe() -> str:
    try:
        return str(year_of(m))
    except KeyError:
        return 'KeyError'


print(probe())
print(sorted(bad_build()))
